using Sigov.Domain.Common;

namespace Sigov.Application.Financeiro;

public abstract class FinanceiroServiceBase
{
    protected FinanceiroServiceBase(ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit) { Tenant = tenant; User = user; Permissions = permissions; Audit = audit; }
    protected ICurrentTenant Tenant { get; }
    protected ICurrentUser User { get; }
    protected IPermissionService Permissions { get; }
    protected IAuditService Audit { get; }
    protected long TenantId => Tenant.TenantId ?? 0;
    protected long EntidadeId => Tenant.EntidadeId ?? 0;
    protected long ExercicioId => Tenant.ExercicioId ?? 0;
    protected long? UsuarioId => User.UsuarioId;
    protected bool EscopoValido => TenantId > 0 && EntidadeId > 0 && ExercicioId > 0;
    protected Result<T> EscopoFailure<T>() => Result<T>.Failure("Tenant, entidade e exercício são obrigatórios para operações financeiras.");
    protected Result EscopoFailure() => Result.Failure("Tenant, entidade e exercício são obrigatórios para operações financeiras.");
    protected async Task<bool> CanAsync(string chave, CancellationToken ct)
    {
        if (!User.UsuarioId.HasValue) return false;
        var partes = chave.Split('.');
        var recurso = partes.Length >= 3 ? $"{partes[0]}.{partes[1]}" : chave;
        var acao = partes.Length >= 3 ? partes[2] : "visualizar";
        return await Permissions.HasPermissionAsync(User.UsuarioId.Value, FinanceiroPermissoes.Modulo, recurso, acao, ct).ConfigureAwait(false);
    }
}

public abstract class CrudFinanceiroService<TCreate, TUpdate, TFiltro, TResponse> : FinanceiroServiceBase
{
    private readonly ICrudFinanceiroRepository<TCreate, TUpdate, TFiltro, TResponse> _repo;
    private readonly ILogger _logger;
    private readonly string _tabela;
    private readonly string _visualizar;
    private readonly string _criar;
    private readonly string _editar;
    private readonly string _excluir;
    protected CrudFinanceiroService(ICrudFinanceiroRepository<TCreate, TUpdate, TFiltro, TResponse> repo, ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit, ILogger logger, string tabela, string visualizar, string criar, string editar, string excluir) : base(tenant, user, permissions, audit)
    { _repo = repo; _logger = logger; _tabela = tabela; _visualizar = visualizar; _criar = criar; _editar = editar; _excluir = excluir; }
    public async Task<Result<PagedResult<TResponse>>> ListarAsync(TFiltro filtro, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<PagedResult<TResponse>>(); if (!await CanAsync(_visualizar, ct).ConfigureAwait(false)) return Result<PagedResult<TResponse>>.Failure("403"); try { return Result<PagedResult<TResponse>>.Success(await _repo.ListarAsync(TenantId, EntidadeId, ExercicioId, filtro, ct).ConfigureAwait(false)); } catch (Exception ex) { _logger.LogError(ex, "Erro ao listar {Tabela}.", _tabela); return Result<PagedResult<TResponse>>.Failure("Erro ao listar registros financeiros."); } }
    public async Task<Result<TResponse>> ObterAsync(long id, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<TResponse>(); if (!await CanAsync(_visualizar, ct).ConfigureAwait(false)) return Result<TResponse>.Failure("403"); var item = await _repo.ObterAsync(TenantId, EntidadeId, ExercicioId, id, ct).ConfigureAwait(false); return item is null ? Result<TResponse>.Failure("Registro não encontrado.") : Result<TResponse>.Success(item); }
    public async Task<Result<long>> CriarAsync(TCreate request, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<long>(); if (!await CanAsync(_criar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); try { var id = await _repo.CriarAsync(TenantId, EntidadeId, ExercicioId, request, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "CRIAR", _tabela, id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, request, ct).ConfigureAwait(false); return Result<long>.Success(id); } catch (Exception ex) { _logger.LogError(ex, "Erro ao criar {Tabela}.", _tabela); return Result<long>.Failure("Erro ao criar registro financeiro."); } }
    public async Task<Result> AtualizarAsync(long id, TUpdate request, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(_editar, ct).ConfigureAwait(false)) return Result.Failure("403"); try { var anterior = await _repo.ObterAsync(TenantId, EntidadeId, ExercicioId, id, ct).ConfigureAwait(false); await _repo.AtualizarAsync(TenantId, EntidadeId, ExercicioId, id, request, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "EDITAR", _tabela, id.ToString(System.Globalization.CultureInfo.InvariantCulture), anterior, request, ct).ConfigureAwait(false); return Result.Success(); } catch (Exception ex) { _logger.LogError(ex, "Erro ao atualizar {Tabela}.", _tabela); return Result.Failure("Erro ao atualizar registro financeiro."); } }
    public async Task<Result> ExcluirAsync(long id, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(_excluir, ct).ConfigureAwait(false)) return Result.Failure("403"); await _repo.ExcluirAsync(TenantId, EntidadeId, ExercicioId, id, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "EXCLUIR", _tabela, id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, null, ct).ConfigureAwait(false); return Result.Success(); }
}

