public sealed class OrcamentoService : FinanceiroServiceBase, IOrcamentoService
{
    private readonly IOrcamentoRepository _repo; private readonly ILogger<OrcamentoService> _logger;
    public OrcamentoService(IOrcamentoRepository repo, ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit, ILogger<OrcamentoService> logger) : base(tenant, user, permissions, audit) { _repo = repo; _logger = logger; }
    public async Task<Result<PagedResult<OrcamentoDespesaResponse>>> ListarDespesasAsync(OrcamentoDespesaFiltro f, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<PagedResult<OrcamentoDespesaResponse>>(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoVisualizar, ct).ConfigureAwait(false)) return Result<PagedResult<OrcamentoDespesaResponse>>.Failure("403"); return Result<PagedResult<OrcamentoDespesaResponse>>.Success(await _repo.ListarDespesasAsync(TenantId, EntidadeId, ExercicioId, f, ct).ConfigureAwait(false)); }
    public async Task<Result<OrcamentoDespesaResponse>> ObterDespesaAsync(long id, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<OrcamentoDespesaResponse>(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoVisualizar, ct).ConfigureAwait(false)) return Result<OrcamentoDespesaResponse>.Failure("403"); var item = await _repo.ObterDespesaAsync(TenantId, EntidadeId, ExercicioId, id, ct).ConfigureAwait(false); return item is null ? Result<OrcamentoDespesaResponse>.Failure("Orçamento não encontrado.") : Result<OrcamentoDespesaResponse>.Success(item); }
    public async Task<Result<long>> CriarDespesaAsync(OrcamentoDespesaCreateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<long>(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoCriar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); if (r.DotacaoInicial < 0m) return Result<long>.Failure("Dotação inicial não pode ser negativa."); try { var id = await _repo.CriarDespesaAsync(TenantId, EntidadeId, ExercicioId, r, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "CRIAR_ORCAMENTO_DESPESA", "sigov.orcamento_despesa", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result<long>.Success(id); } catch (Exception ex) { _logger.LogError(ex, "Erro ao criar orçamento da despesa."); return Result<long>.Failure("Erro ao criar orçamento da despesa."); } }
    public async Task<Result> AtualizarDespesaAsync(long id, OrcamentoDespesaUpdateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoEditar, ct).ConfigureAwait(false)) return Result.Failure("403"); await _repo.AtualizarDespesaAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, ct).ConfigureAwait(false); return Result.Success(); }
    public async Task<Result> MovimentarDespesaAsync(long id, MovimentacaoOrcamentariaRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoMovimentar, ct).ConfigureAwait(false)) return Result.Failure("403"); await _repo.MovimentarDespesaAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "ORCAMENTO_MOVIMENTADO", "sigov.orcamento_movimentacao", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result.Success(); }
    public async Task<Result<PagedResult<OrcamentoReceitaResponse>>> ListarReceitasAsync(OrcamentoReceitaFiltro f, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<PagedResult<OrcamentoReceitaResponse>>(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoVisualizar, ct).ConfigureAwait(false)) return Result<PagedResult<OrcamentoReceitaResponse>>.Failure("403"); return Result<PagedResult<OrcamentoReceitaResponse>>.Success(await _repo.ListarReceitasAsync(TenantId, EntidadeId, ExercicioId, f, ct).ConfigureAwait(false)); }
    public async Task<Result<OrcamentoReceitaResponse>> ObterReceitaAsync(long id, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<OrcamentoReceitaResponse>(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoVisualizar, ct).ConfigureAwait(false)) return Result<OrcamentoReceitaResponse>.Failure("403"); var item = await _repo.ObterReceitaAsync(TenantId, EntidadeId, ExercicioId, id, ct).ConfigureAwait(false); return item is null ? Result<OrcamentoReceitaResponse>.Failure("Orçamento não encontrado.") : Result<OrcamentoReceitaResponse>.Success(item); }
    public async Task<Result<long>> CriarReceitaAsync(OrcamentoReceitaCreateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<long>(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoCriar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); var id = await _repo.CriarReceitaAsync(TenantId, EntidadeId, ExercicioId, r, UsuarioId, ct).ConfigureAwait(false); return Result<long>.Success(id); }
    public async Task<Result> AtualizarReceitaAsync(long id, OrcamentoReceitaUpdateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.OrcamentoEditar, ct).ConfigureAwait(false)) return Result.Failure("403"); await _repo.AtualizarReceitaAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, ct).ConfigureAwait(false); return Result.Success(); }
}

public sealed class EmpenhoService : FinanceiroServiceBase, IEmpenhoService
{
    private readonly IEmpenhoRepository _repo; private readonly IFinanceiroSequencialService _seq; private readonly ILogger<EmpenhoService> _logger;
    public EmpenhoService(IEmpenhoRepository repo, IFinanceiroSequencialService seq, ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit, ILogger<EmpenhoService> logger) : base(tenant, user, permissions, audit) { _repo = repo; _seq = seq; _logger = logger; }
    public async Task<Result<PagedResult<EmpenhoResumoResponse>>> ListarAsync(EmpenhoFiltro f, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<PagedResult<EmpenhoResumoResponse>>(); if (!await CanAsync(FinanceiroPermissoes.EmpenhoVisualizar, ct).ConfigureAwait(false)) return Result<PagedResult<EmpenhoResumoResponse>>.Failure("403"); return Result<PagedResult<EmpenhoResumoResponse>>.Success(await _repo.ListarAsync(TenantId, EntidadeId, ExercicioId, f, ct).ConfigureAwait(false)); }
    public async Task<Result<EmpenhoDetalheResponse>> ObterAsync(long id, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<EmpenhoDetalheResponse>(); if (!await CanAsync(FinanceiroPermissoes.EmpenhoVisualizar, ct).ConfigureAwait(false)) return Result<EmpenhoDetalheResponse>.Failure("403"); var item = await _repo.ObterAsync(TenantId, EntidadeId, ExercicioId, id, ct).ConfigureAwait(false); return item is null ? Result<EmpenhoDetalheResponse>.Failure("Empenho não encontrado.") : Result<EmpenhoDetalheResponse>.Success(item); }
    public async Task<Result<long>> CriarAsync(EmpenhoCreateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<long>(); if (!await CanAsync(FinanceiroPermissoes.EmpenhoCriar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); if (r.FornecedorPessoaId <= 0 || r.Itens.Count == 0 || r.Itens.Sum(i => i.Quantidade * i.ValorUnitario) <= 0m) return Result<long>.Failure("Empenho exige fornecedor, itens e valor maior que zero."); try { var ano = r.DataEmpenho.Year; var numero = await _seq.ProximoAsync(TenantId, EntidadeId, ExercicioId, ano, "empenho", "EMP", ct).ConfigureAwait(false); var id = await _repo.CriarAsync(TenantId, EntidadeId, ExercicioId, numero, ano, r, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "EMPENHO_EMITIDO", "sigov.empenho", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result<long>.Success(id); } catch (Exception ex) { _logger.LogError(ex, "Erro ao emitir empenho."); return Result<long>.Failure("Erro ao emitir empenho. Verifique saldo disponível e exercício."); } }
    public async Task<Result> AtualizarAsync(long id, EmpenhoUpdateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.EmpenhoEditar, ct).ConfigureAwait(false)) return Result.Failure("403"); await _repo.AtualizarAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, ct).ConfigureAwait(false); return Result.Success(); }
    public async Task<Result> AnularAsync(long id, AnularEmpenhoRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.EmpenhoAnular, ct).ConfigureAwait(false)) return Result.Failure("403"); await _repo.AnularAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "EMPENHO_ANULADO", "sigov.empenho", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result.Success(); }
}

public sealed class LiquidacaoService : FinanceiroServiceBase, ILiquidacaoService { private readonly ILiquidacaoRepository _repo; private readonly IFinanceiroSequencialService _seq; public LiquidacaoService(ILiquidacaoRepository repo, IFinanceiroSequencialService seq, ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit) : base(tenant, user, permissions, audit) { _repo = repo; _seq = seq; } public async Task<Result<PagedResult<LiquidacaoResponse>>> ListarAsync(LiquidacaoFiltro f, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<PagedResult<LiquidacaoResponse>>(); if (!await CanAsync(FinanceiroPermissoes.LiquidacaoVisualizar, ct).ConfigureAwait(false)) return Result<PagedResult<LiquidacaoResponse>>.Failure("403"); return Result<PagedResult<LiquidacaoResponse>>.Success(await _repo.ListarAsync(TenantId, EntidadeId, ExercicioId, f, ct).ConfigureAwait(false)); } public async Task<Result<LiquidacaoResponse>> ObterAsync(long id, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<LiquidacaoResponse>(); if (!await CanAsync(FinanceiroPermissoes.LiquidacaoVisualizar, ct).ConfigureAwait(false)) return Result<LiquidacaoResponse>.Failure("403"); var item = await _repo.ObterAsync(TenantId, EntidadeId, ExercicioId, id, ct).ConfigureAwait(false); return item is null ? Result<LiquidacaoResponse>.Failure("Liquidação não encontrada.") : Result<LiquidacaoResponse>.Success(item); } public async Task<Result<long>> CriarAsync(long empenhoId, LiquidacaoCreateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<long>(); if (!await CanAsync(FinanceiroPermissoes.LiquidacaoCriar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); var numero = await _seq.ProximoAsync(TenantId, EntidadeId, ExercicioId, r.DataLiquidacao.Year, "liquidacao", "LIQ", ct).ConfigureAwait(false); var id = await _repo.CriarAsync(TenantId, EntidadeId, ExercicioId, empenhoId, numero, r, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "EMPENHO_LIQUIDADO", "sigov.liquidacao", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result<long>.Success(id); } public async Task<Result> AnularAsync(long id, AnularLiquidacaoRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.LiquidacaoAnular, ct).ConfigureAwait(false)) return Result.Failure("403"); await _repo.AnularAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, ct).ConfigureAwait(false); return Result.Success(); } }
public sealed class PagamentoService : FinanceiroServiceBase, IPagamentoService { private readonly IPagamentoRepository _repo; private readonly IFinanceiroSequencialService _seq; public PagamentoService(IPagamentoRepository repo, IFinanceiroSequencialService seq, ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit) : base(tenant, user, permissions, audit) { _repo = repo; _seq = seq; } public async Task<Result<PagedResult<PagamentoResponse>>> ListarAsync(PagamentoFiltro f, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<PagedResult<PagamentoResponse>>(); if (!await CanAsync(FinanceiroPermissoes.PagamentoVisualizar, ct).ConfigureAwait(false)) return Result<PagedResult<PagamentoResponse>>.Failure("403"); return Result<PagedResult<PagamentoResponse>>.Success(await _repo.ListarAsync(TenantId, EntidadeId, ExercicioId, f, ct).ConfigureAwait(false)); } public async Task<Result<PagamentoResponse>> ObterAsync(long id, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<PagamentoResponse>(); if (!await CanAsync(FinanceiroPermissoes.PagamentoVisualizar, ct).ConfigureAwait(false)) return Result<PagamentoResponse>.Failure("403"); var item = await _repo.ObterAsync(TenantId, EntidadeId, ExercicioId, id, ct).ConfigureAwait(false); return item is null ? Result<PagamentoResponse>.Failure("Pagamento não encontrado.") : Result<PagamentoResponse>.Success(item); } public async Task<Result<long>> CriarAsync(long liquidacaoId, PagamentoCreateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<long>(); if (!await CanAsync(FinanceiroPermissoes.PagamentoCriar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); if (r.Valor <= 0m) return Result<long>.Failure("O valor do pagamento deve ser maior que zero."); if (string.IsNullOrWhiteSpace(r.FormaPagamento)) return Result<long>.Failure("A forma de pagamento é obrigatória."); var numero = await _seq.ProximoAsync(TenantId, EntidadeId, ExercicioId, r.DataPagamento.Year, "pagamento", "PAG", ct).ConfigureAwait(false); var id = await _repo.CriarAsync(TenantId, EntidadeId, ExercicioId, liquidacaoId, numero, r, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "PAGAMENTO_REALIZADO", "sigov.pagamento", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result<long>.Success(id); } public async Task<Result> CancelarAsync(long id, CancelarPagamentoRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure(); if (!await CanAsync(FinanceiroPermissoes.PagamentoCancelar, ct).ConfigureAwait(false)) return Result.Failure("403"); if (string.IsNullOrWhiteSpace(r.Motivo)) return Result.Failure("O estorno exige justificativa."); var anterior = await _repo.ObterAsync(TenantId, EntidadeId, ExercicioId, id, ct).ConfigureAwait(false); if (anterior is null) return Result.Failure("Pagamento não encontrado."); await _repo.CancelarAsync(TenantId, EntidadeId, ExercicioId, id, r, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "PAGAMENTO_ESTORNADO", "sigov.pagamento", id.ToString(System.Globalization.CultureInfo.InvariantCulture), anterior, new { Status = "CANCELADO", r.Motivo }, ct).ConfigureAwait(false); return Result.Success(); } }
public sealed class ReceitaService : FinanceiroServiceBase, IReceitaService { private readonly IReceitaRepository _repo; private readonly IFinanceiroSequencialService _seq; public ReceitaService(IReceitaRepository repo, IFinanceiroSequencialService seq, ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit) : base(tenant, user, permissions, audit) { _repo = repo; _seq = seq; } public async Task<Result<PagedResult<ReceitaLancamentoResponse>>> ListarLancamentosAsync(ReceitaLancamentoFiltro f, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<PagedResult<ReceitaLancamentoResponse>>(); if (!await CanAsync(FinanceiroPermissoes.ReceitaVisualizar, ct).ConfigureAwait(false)) return Result<PagedResult<ReceitaLancamentoResponse>>.Failure("403"); return Result<PagedResult<ReceitaLancamentoResponse>>.Success(await _repo.ListarLancamentosAsync(TenantId, EntidadeId, ExercicioId, f, ct).ConfigureAwait(false)); } public async Task<Result<ReceitaLancamentoResponse>> ObterLancamentoAsync(long id, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<ReceitaLancamentoResponse>(); if (!await CanAsync(FinanceiroPermissoes.ReceitaVisualizar, ct).ConfigureAwait(false)) return Result<ReceitaLancamentoResponse>.Failure("403"); var item = await _repo.ObterLancamentoAsync(TenantId, EntidadeId, ExercicioId, id, ct).ConfigureAwait(false); return item is null ? Result<ReceitaLancamentoResponse>.Failure("Receita não encontrada.") : Result<ReceitaLancamentoResponse>.Success(item); } public async Task<Result<long>> CriarLancamentoAsync(ReceitaLancamentoCreateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<long>(); if (!await CanAsync(FinanceiroPermissoes.ReceitaCriar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); var numero = await _seq.ProximoAsync(TenantId, EntidadeId, ExercicioId, r.DataLancamento.Year, "receita_lancamento", "REC", ct).ConfigureAwait(false); var id = await _repo.CriarLancamentoAsync(TenantId, EntidadeId, ExercicioId, numero, r, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "RECEITA_LANCADA", "sigov.receita_lancamento", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result<long>.Success(id); } public async Task<Result<long>> ArrecadarAsync(long lancamentoId, ReceitaArrecadacaoCreateRequest r, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<long>(); if (!await CanAsync(FinanceiroPermissoes.ReceitaArrecadar, ct).ConfigureAwait(false)) return Result<long>.Failure("403"); var numero = await _seq.ProximoAsync(TenantId, EntidadeId, ExercicioId, r.DataArrecadacao.Year, "receita_arrecadacao", "ARR", ct).ConfigureAwait(false); var id = await _repo.ArrecadarAsync(TenantId, EntidadeId, ExercicioId, lancamentoId, numero, r, UsuarioId, ct).ConfigureAwait(false); await Audit.RegistrarAsync("financeiro", "RECEITA_ARRECADADA", "sigov.receita_arrecadacao", id.ToString(System.Globalization.CultureInfo.InvariantCulture), null, r, ct).ConfigureAwait(false); return Result<long>.Success(id); } }
public sealed class FinanceiroDashboardService : FinanceiroServiceBase, IFinanceiroDashboardService { private readonly IFinanceiroDashboardRepository _repo; public FinanceiroDashboardService(IFinanceiroDashboardRepository repo, ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit) : base(tenant, user, permissions, audit) { _repo = repo; } public async Task<Result<FinanceiroDashboardResponse>> ObterAsync(CancellationToken ct) { if (!EscopoValido) return EscopoFailure<FinanceiroDashboardResponse>(); if (!await CanAsync(FinanceiroPermissoes.DashboardVisualizar, ct).ConfigureAwait(false)) return Result<FinanceiroDashboardResponse>.Failure("403"); return Result<FinanceiroDashboardResponse>.Success(await _repo.ObterAsync(TenantId, EntidadeId, ExercicioId, ct).ConfigureAwait(false)); } }
public sealed class FinanceiroExportacaoService : FinanceiroServiceBase, IFinanceiroExportacaoService { public FinanceiroExportacaoService(ICurrentTenant tenant, ICurrentUser user, IPermissionService permissions, IAuditService audit) : base(tenant, user, permissions, audit) { } public async Task<Result<byte[]>> ExportarAsync(string recurso, string formato, CancellationToken ct) { if (!EscopoValido) return EscopoFailure<byte[]>(); if (!await CanAsync(FinanceiroPermissoes.Exportar, ct).ConfigureAwait(false)) return Result<byte[]>.Failure("403"); await Audit.RegistrarAsync("financeiro", "EXPORTAR", $"financeiro.{recurso}", formato, null, new { recurso, formato }, ct).ConfigureAwait(false); var payload = formato.Equals("json", StringComparison.OrdinalIgnoreCase) ? "[]" : "id;numero;valor\n"; return Result<byte[]>.Success(Encoding.UTF8.GetBytes(payload)); } }
